<script setup lang="ts">
import { Heart, Minus, Plus, Truck } from 'lucide-vue-next'; import { products, categories, formatPrice } from '~/data/catalog'
const route=useRoute(); const product=computed(()=>products.find(p=>p.id===route.params.id)); const qty=ref(1); const color=ref(''); const {add,favorites,toggleFavorite}=useShop();
watchEffect(() => {
  if (product.value && !color.value) color.value = product.value.colors[0] ?? ''
})
</script>
<template><section v-if="product" class="container-page py-12"><p class="mb-8 text-xs text-secondary">Главная / {{ categories.find(c=>c.id===product!.categoryId)?.name }} / {{ product.name }}</p><div class="grid gap-10 lg:grid-cols-2 lg:gap-20"><div class="aspect-[4/5] bg-surface"><img :src="product.image" :alt="product.name" class="h-full w-full object-cover"></div><div class="py-4"><p class="mb-4 text-xs uppercase tracking-wider text-secondary">Артикул {{ product.article }}</p><h1 class="mb-6 text-4xl font-light leading-tight md:text-5xl">{{ product.name }}</h1><div class="mb-10 flex gap-3 text-xl"><b>{{ formatPrice(product.price) }}</b><s v-if="product.oldPrice" class="text-secondary">{{ formatPrice(product.oldPrice) }}</s></div><div class="mb-8"><p class="mb-3 text-sm font-medium">Цвет: {{ color }}</p><div class="flex flex-wrap gap-2"><button v-for="c in product.colors" :key="c" class="border px-4 py-2 text-sm" :class="c===color?'border-primary':'border-border'" @click="color=c">{{ c }}</button></div></div><div class="mb-6 flex gap-3"><div class="flex items-center border border-border"><button class="p-3" @click="qty=Math.max(1,qty-1)"><Minus class="h-4"/></button><span class="w-8 text-center">{{ qty }}</span><button class="p-3" @click="qty++"><Plus class="h-4"/></button></div><button class="btn-primary flex-1" :disabled="!product.inStock" @click="add(product!,qty,color)">{{ product.inStock?'Добавить в корзину':'Под заказ' }}</button><button class="border border-border p-3" @click="toggleFavorite(product.id)"><Heart :class="favorites.includes(product.id)&&'fill-primary'"/></button></div><div class="flex items-center gap-3 border-t border-border py-6 text-sm"><Truck/><span>Доставка по Москве от 2 рабочих дней</span></div><p class="leading-7 text-secondary">Лаконичная геометрия, долговечные материалы и продуманная эргономика. Подходит для современных рабочих пространств.</p></div></div></section><section v-else class="container-page py-24"><h1 class="text-4xl">Товар не найден</h1></section></template>
